-- Accounts mit Instagram-Anmeldung, deren Schlüssel verlängert werden muss (Stefan 18.10.2026, Vertrag Migration 45, 4.4).
-- Gibt Schlüssel im Klartext aus: nur in diesem Workflow (Ausführungsdaten werden nicht gespeichert).
SELECT talents_verlaengern_liste() AS r;

parameters.jsCode:
// Kanäle vorbereiten (Stefan 18.10.2026, Vertrag Migration 45, 4.4): Accounts mit Instagram-Anmeldung, deren Schlüssel
// verlängert werden muss (talents_verlaengern_liste), OHNE Zugangsschlüssel weitergeben.
// Den Schlüssel liest nur "Schlüssel verlängern" (Abfrage-Parameter access_token, laut Meta-Doku) direkt aus "Liste holen".
const ADRESSE = 'https://graph.instagram.com/refresh_access_token'; // Meta-Doku "Refresh Access Token": GET, ohne Versionsnummer
const r = $input.first().json.r || {};
if (r.ok !== true) throw new Error('Talents-Verlängerung: ' + String(r.fehler || 'Die Liste der Instagram-Accounts ist nicht lesbar.').slice(0, 200));
const out = [];
for (const k of Array.isArray(r.kanaele) ? r.kanaele : []) {
  const id = Number(k && k.kanal_id);
  if (!(id > 0)) continue;
  let fehler = null;
  if (k.schluessel_fehler === true || typeof k.schluessel !== 'string' || !k.schluessel.trim()) {
    fehler = { code: 'schluessel', text: 'Zugangsschlüssel nicht lesbar.' };
  } else if (String(k.adresse || '') !== ADRESSE) {
    fehler = { code: 'adresse', text: 'Unerwartete Adresse für die Verlängerung des Zugangsschlüssels. Nichts verlängert.' };
  }
  out.push({ json: { kanal_id: id, adresse: ADRESSE, fehler } });
}
return out;

// Antwort auswerten (Stefan 18.10.2026, Vertrag Migration 45, 4.4): je Account Erfolg oder Fehler, ohne Zugangsschlüssel.
// Antwort laut Meta-Doku: { access_token, token_type, expires_in }. Der neue Schlüssel bleibt in der Antwort von
// "Schlüssel verlängern"; "Ergebnis speichern" liest ihn dort direkt (nr = Position der Antwort).
// Reihenfolge der Antworten = Reihenfolge der Accounts aus "Verlängern?" (wahr-Zweig).
// Scheitert nach einer erfolgreichen Verlängerung das Speichern, ist der neue Schlüssel verloren: Der Fehler wird über
// talents_abruf_fehler vermerkt, der nächste Lauf versucht es mit dem gespeicherten Schlüssel erneut (entschieden 18.10.2026).
const SECHZIG_TAGE = 5184000; // laut Meta-Doku gilt ein verlängerter Schlüssel 60 Tage (nur falls expires_in fehlt)
const SCHLUESSEL_MUSTER = /(EAA|IGAA|IGQV)[A-Za-z0-9_|-]{16,}/g;
function kurz(t, n) {
  // Adressen (z. B. in Netzfehlern) nur ohne Parameter melden, access_token nie (Stefan 18.10.2026)
  return String(t == null ? '' : t)
    .replace(/(https?:\/\/[^\s?#"']+)[?#][^\s"']*/gi, '$1')
    .replace(/(graph\.instagram\.com[^\s?#"']*)[?#][^\s"']*/gi, '$1')
    .replace(SCHLUESSEL_MUSTER, '***').replace(/(access_token|client_secret|fb_exchange_token)=[^&\s"']+/gi, '$1=***')
    .replace(/\s+/g, ' ').trim().slice(0, n || 200);
}
function zahl(v) {
  if (typeof v === 'number' && isFinite(v)) return v;
  if (typeof v === 'string' && /^[0-9]{1,12}$/.test(v.trim())) return Number(v.trim());
  return null;
}
const VORSPANN = 'Verlängerung des Zugangsschlüssels fehlgeschlagen. ';
const kanaele = $('Verlängern?').all(0);
const antworten = $input.all();
return antworten.map((a, i) => {
  let q = kanaele[i];
  if (kanaele.length !== antworten.length) {
    const p = Array.isArray(a.pairedItem) ? a.pairedItem[0] : a.pairedItem;
    q = p && typeof p.item === 'number' ? kanaele[p.item] : undefined;
  }
  const k = (q || {}).json || {};
  const r = a.json || {};
  const status = Number(r.statusCode);
  const body = r.body && typeof r.body === 'object' ? r.body : null;
  const e = body && body.error && typeof body.error === 'object' ? body.error : null;
  let fehler = null, gueltig_bis = null;
  if (e) {
    const code = Number(e.code);
    const sub = e.error_subcode ? ' (Untercode ' + kurz(e.error_subcode, 12) + ')' : '';
    fehler = { code: isFinite(code) ? String(code) : 'graph', text: VORSPANN + 'Instagram meldet: ' + kurz(e.message || e.error_user_msg || e.type || '', 160) + sub };
  } else if (!status) {
    fehler = { code: 'netz', text: VORSPANN + 'Instagram war nicht erreichbar (' + kurz(r.error && (r.error.message || r.error), 120) + ').' };
  } else if (status < 200 || status >= 300 || !body) {
    fehler = { code: 'http' + status, text: VORSPANN + 'Unerwartete Antwort von Instagram (HTTP ' + status + ').' };
  } else if (typeof body.access_token !== 'string' || body.access_token.length < 20 || /\s/.test(body.access_token)) {
    fehler = { code: 'antwort', text: VORSPANN + 'Instagram hat keinen neuen Schlüssel geliefert.' };
  } else {
    gueltig_bis = zahl(body.expires_in) > 0 ? zahl(body.expires_in) : SECHZIG_TAGE;
  }
  // Code 190 = Schlüssel abgelaufen oder entzogen (Vertrag 4.4: abgelaufen = code '190')
  if (fehler) fehler.abgelaufen = fehler.code === '190';
  return { json: { kanal_id: k.kanal_id, nr: i, speichern: !fehler, gueltig_bis, fehler } };
});
